using StructuralSolver2D.Analysis.Results;

namespace StructuralSolver2D.Analysis.PublicApi;

/// <summary>
/// One explicitly selected linear-elastic static load case or manual combination.
/// The order of the input scenarios is preserved for deterministic equal-value ties.
/// No normative load combinations are generated by this contract.
/// </summary>
public sealed record StaticForceEnvelopeScenarioM79(StructuralAnalysisTargetKind Kind, string Id);

/// <summary>
/// Governing analytical section-force extreme, including its originating analysis.
/// Normal/shear forces are in kN, bending moments in kNm; distance is in m.
/// At a concentrated load, Side identifies the one-sided limit.
/// </summary>
public sealed record GoverningForceExtremeM79(
    string MemberId,
    StructuralAnalysisTargetKind TargetKind,
    string ResultId,
    InternalForceQuantity Quantity,
    double Value,
    double Distance,
    double Position,
    SectionLimitM78 Side);

/// <summary>Global extrema over the selected scenarios for one Frame2D member.</summary>
public sealed class FrameMemberForceEnvelopeM79
{
    public FrameMemberForceEnvelopeM79(
        string memberId,
        IReadOnlyList<GoverningForceExtremeM79> minima,
        IReadOnlyList<GoverningForceExtremeM79> maxima,
        IReadOnlyList<GoverningForceExtremeM79> maximumMagnitudes)
    {
        MemberId = memberId;
        Minima = minima;
        Maxima = maxima;
        MaximumMagnitudes = maximumMagnitudes;
    }

    public string MemberId { get; }
    public IReadOnlyList<GoverningForceExtremeM79> Minima { get; }
    public IReadOnlyList<GoverningForceExtremeM79> Maxima { get; }
    public IReadOnlyList<GoverningForceExtremeM79> MaximumMagnitudes { get; }

    public GoverningForceExtremeM79 Minimum(InternalForceQuantity quantity) =>
        Minima.Single(e => e.Quantity == quantity);

    public GoverningForceExtremeM79 Maximum(InternalForceQuantity quantity) =>
        Maxima.Single(e => e.Quantity == quantity);

    public GoverningForceExtremeM79 MaximumAbsolute(InternalForceQuantity quantity) =>
        MaximumMagnitudes.Single(e => e.Quantity == quantity);
}

/// <summary>
/// Exact global extrema on Frame2D members for the explicitly supplied load targets.
/// This is NOT a section-by-section continuous envelope curve, a Truss2D envelope,
/// a design code check, or an automatic SLU/SLE combination generator.
/// </summary>
public sealed class StructuralStaticForceEnvelopeM79
{
    public StructuralStaticForceEnvelopeM79(
        IReadOnlyList<StaticForceEnvelopeScenarioM79> scenarios,
        IReadOnlyList<FrameMemberForceEnvelopeM79> members)
    {
        Scenarios = scenarios;
        Members = members;
    }

    public IReadOnlyList<StaticForceEnvelopeScenarioM79> Scenarios { get; }
    public IReadOnlyList<FrameMemberForceEnvelopeM79> Members { get; }

    public FrameMemberForceEnvelopeM79 GetMember(string memberId) =>
        Members.First(member => string.Equals(member.MemberId, memberId, StringComparison.OrdinalIgnoreCase));
}
